"""Write `.env.example` from the Settings class, so the documented key
list can never drift from the code.

    uv run python -m tools.gen_env_example           # write
    uv run python -m tools.gen_env_example --check   # CI: fail when stale
"""

from __future__ import annotations

import sys
from pathlib import Path

from pydantic_core import PydanticUndefined

from app.core.settings import Settings

OUT = Path(__file__).resolve().parent.parent / ".env.example"

HEADER = """# Earth DNA backend — every key the service reads, with its default.
# Generated by tools/gen_env_example.py from app/core/settings.py; do not edit by hand.
#
# Deployed environments do not use this file: the ECS task definition injects
# the whole per-environment secret as APP_CONFIG (one JSON object with these
# keys) plus APP_ENV. Locally, copy to .env and fill the blanks.
#
# Required (no default): JWT_SECRET (>= 32 chars). Generate:
#   python -c "import secrets; print(secrets.token_hex(32))"
"""


def render() -> str:
    lines = [HEADER]
    for name, field in Settings.model_fields.items():
        default = field.default
        if field.default_factory is not None:
            default = field.default_factory()  # type: ignore[call-arg]
        if default is PydanticUndefined:
            shown = ""
        elif isinstance(default, list):
            shown = ",".join(str(x) for x in default)
        elif isinstance(default, bool):
            shown = "true" if default else "false"
        elif default is None:
            shown = ""
        else:
            shown = str(default)
        lines.append(f"{name}={shown}")
    return "\n".join(lines) + "\n"


def main() -> None:
    if "--check" in sys.argv:
        current = OUT.read_text(encoding="utf-8") if OUT.exists() else ""
        if current != render():
            print(
                f"{OUT.name} is out of date: run `uv run python -m tools.gen_env_example`"
            )
            raise SystemExit(1)
        print(f"{OUT.name} matches settings.py")
        return
    OUT.write_text(render(), encoding="utf-8")
    print(f"wrote {OUT} ({len(Settings.model_fields)} keys)")


if __name__ == "__main__":
    main()
